#!/usr/bin/env bash
# AKFC — Demandes (tickets), incrément 2b : formulaire « Écrire au club » sur la page Contacts.
#  - features/contact/ContactForm.tsx : connecté = identité du compte affichée (non saisie) ;
#    visiteur = nom + adresse (obligatoire) ; choix du destinataire si plusieurs catégories ;
#    champ piège invisible ; confirmation avec référence AKFC-xxxx et date de réponse promise.
#  - page Contacts : formulaire + carte « Coordonnées » côte à côte (empilés sur mobile).
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-tickets-increment2b.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
[ -f packages/backend/src/modules/tickets/router.ts ] || { echo "ERREUR: applique d'abord apply-tickets-increment2.sh." >&2; exit 1; }
FORM="apps/web/src/features/contact/ContactForm.tsx"
PAGE="apps/web/src/app/(public)/contacts/page.tsx"
[ -f "$FORM" ] && { echo "— déjà appliqué"; exit 0; }
[ -f "$PAGE" ] || { echo "ERREUR: $PAGE introuvable." >&2; exit 1; }
BK=/tmp/akfc_tk2b_backup; rm -rf "$BK"; mkdir -p "$BK"; cp "$PAGE" "$BK/page.tsx"
restore(){ cp "$BK/page.tsx" "$PAGE"; rm -f "$FORM"; rmdir apps/web/src/features/contact 2>/dev/null || true; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }

W=/tmp/akfc_tk2b; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/page_edit.py"
echo '' | base64 -d > "$W/ContactForm.tsx"

echo "== application =="
mkdir -p apps/web/src/features/contact && cp "$W/ContactForm.tsx" "$FORM" && echo "  ok  $FORM"
python3 "$W/page_edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

git add "$FORM" "$PAGE"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(contact): formulaire « Écrire au club » (crée une demande)

